    {
      "id": "m51",
      "about_topic": true,
      "says": "fact: motorcycles/bicycles/mopeds may pull to side to avoid hazards or be seen; rule: do not pass in the same lane; rule: pass by changing lanes"
    },
    {
      "id": "m1",
      "about_topic": true,
      "says": "fact: changing position involves changing lanes or overtaking/passing"
    },
    {
      "id": "m4",
      "about_topic": true,
      "says": "rule: ensure enough space and time to complete the move safely before beginning"
    },
    {
      "id": "m2",
      "about_topic": true,
      "says": "definition: passing is changing lanes to move past a slower vehicle"
    },
    {
      "id": "m3",
      "about_topic": true,
      "says": "fact: not all vehicles travel at the same speed; examples of slower vehicles (cyclists, road service, turning); fact: driver may want to pass slow-moving vehicles"
    },
    {
      "id": "m5",
      "about_topic": true,
      "says": "rule: never overtake/pass unless sure it can be done without danger"
    },
    {
      "id": "m72",
      "about_topic": true,
      "says": "rule: do not pass moving snow plows under any conditions"
    },
    {
      "id": "m6",
      "about_topic": true,
      "says": "rule: if in doubt, do not pass"
    },
    {
      "id": "m8",
      "about_topic": true,
      "says": "lead: steps for passing a vehicle"
    },
    {
      "id": "m9",
      "about_topic": true,
      "says": "procedure step: use left-turn signal and check way is clear before moving into passing lane"
    },
    {
      "id": "m10",
      "about_topic": true,
      "says": "procedure step: watch for hidden bicycles/small vehicles, turning vehicles, and entering vehicles/pedestrians"
    },
    {
      "id": "m11",
      "about_topic": true,
      "says": "procedure step: change lanes after signalling; signal to move back; move back when entire front of passed vehicle is visible in inside mirror"
    },
    {
      "id": "m12",
      "about_topic": true,
      "says": "rule: be careful not to cut off a vehicle by suddenly moving in front of it"
    },
    {
      "id": "m13",
      "about_topic": true,
      "says": "rule: if vehicle being passed speeds up, do not race; go back to original lane"
    },
    {
      "id": "m85",
      "about_topic": true,
      "says": "rule: do not speed up when another driver is trying to pass; it is unlawful and dangerous"
    },
    {
      "id": "m14",
      "about_topic": true,
      "says": "figure: diagram of how to pass another vehicle"
    },
    {
      "id": "m15",
      "about_topic": true,
      "says": "rule: passing within 30 metres of a pedestrian crossover is not permitted"
    },
    {
      "id": "m17",
      "about_topic": true,
      "says": "rule: passing left of a centreline is not permitted 30 metres from a bridge, viaduct or tunnel"
    },
    {
      "id": "m18",
      "about_topic": true,
      "says": "rule: do not attempt to pass when approaching crest of hill or on curve with obstructed vision and insufficient clear distance"
