    {
      "id": "m90",
      "about_topic": true,
      "says": "fact: trucks not allowed in far left lane on many high-speed roads with 3+ lanes; fact: next lane is truck passing lane; rule: if in this lane and truck wants to pass, move to right-hand lane as soon as possible"
    },
    {
      "id": "m52",
      "about_topic": true,
      "says": "figure: diagram of how to pass another vehicle"
    },
    {
      "id": "m39",
      "about_topic": true,
      "says": "rule: be very careful when passing other vehicles at night"
