      "id": "m38",
      "about_topic": true,
      "says": "rule: may drive on right shoulder only to pass a vehicle turning left and only if paved; rule: may not pass on left shoulder"
    },
    {
      "id": "m35",
      "about_topic": true,
      "says": "fact: most passing is done on the left; rule: may pass on right on multi-lane/one-way roads and when overtaking streetcar or left-turning vehicle"
    },
    {
      "id": "m36",
      "about_topic": true,
      "says": "fact: passing on the right can be more dangerous than passing on the left"
    },
    {
      "id": "m37",
      "about_topic": true,
      "says": "rule: if in leftmost lane with slower vehicle ahead, wait for it to move right; do not suddenly change lanes to pass on right"
    },
    {
      "id": "m61",
      "about_topic": true,
      "says": "figure: diagram of vehicle stopped 2 metres behind rear doors of stopped streetcar"
    },
    {
      "id": "m62",
      "about_topic": true,
      "says": "rule: must pass streetcars on the right unless driving on one-way road"
    },
    {
      "id": "m63",
      "about_topic": true,
      "says": "rule: at streetcar stops, stay at least 2 metres behind rear doors where passengers are getting on/off; exception: stops with set-aside area"
    },
    {
      "id": "m64",
      "about_topic": true,
      "says": "rule: always pass streetcar passenger areas at reasonable speed and be prepared for pedestrians to make sudden moves"
    }
